class VersionInfo: def __setattr__(self, name, value): if name in ['major', 'minor', 'patch', 'prerelease', 'build']: raise AttributeError('Cannot modify version components')
class TestVersionInfo(unittest.TestCase): def test_modify_version_component(self): v = VersionInfo(1, 2, 3, 'alpha', '001') with self.assertRaises(AttributeError): v.major = 2
self.assertTrue(True)
